import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, clamp, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, DirectionalLight, Object3D } = ctx.THREE;

  const root = new Group();
  root.name = 'brand-mark-wall';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const stops = colors.gradientStops || [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // STAGE: backdrop plane 7x6 at z=-2.5, vertical gradient from spec
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  // gradientStops: at 0 -> top of visual ramp; uv().y is 0 at bottom, 1 at top
  backdropMat.colorNode = mix(
    color(stops[stops.length - 1].hex),
    color(stops[0].hex),
    clamp(uv().y, 0.0, 1.0)
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // LOCAL RIM LIGHT (accent hue, node-local, <=1.5) — sweeps brushed
  // highlights opposite the scene key
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(accent, 0.6);
  rim.position.set(-3.2, 1.6, -1.4);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0, 0);
  root.add(rimTarget);
  rim.target = rimTarget;
  root.add(rim);

  const fill = new DirectionalLight(paper, 0.45);
  fill.position.set(3.0, 2.4, 2.5);
  const fillTarget = new Object3D();
  root.add(fillTarget);
  fill.target = fillTarget;
  root.add(fill);

  // ---------------------------------------------------------------
  // TILE GEOMETRY: 1.0 x 0.62, chamfer 0.02, shallow extrusion
  // ---------------------------------------------------------------
  const TILE_W = 1.0;
  const TILE_H = 0.62;
  const CHAMFER = 0.02;
  const DEPTH = 0.03;
  const GAP = 0.25;

  const shape = new Shape();
  const hw = TILE_W / 2 - CHAMFER;
  const hh = TILE_H / 2 - CHAMFER;
  shape.moveTo(-hw, -hh);
  shape.lineTo(hw, -hh);
  shape.lineTo(hw, hh);
  shape.lineTo(-hw, hh);
  shape.lineTo(-hw, -hh);

  const tileGeo = new ExtrudeGeometry(shape, {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: CHAMFER,
    bevelSize: CHAMFER,
    bevelSegments: 2
  });
  disposables.push(tileGeo);

  // Machined-metal albedo: vertical ramp #1a1a22 (top) -> #121218 (bottom)
  const rampT = clamp(positionLocal.y.add(TILE_H / 2).div(TILE_H), 0.0, 1.0);
  const tileColorNode = mix(color(stops[stops.length - 1].hex), color(stops[0].hex), rampT);

  function makeTileMaterial() {
    const m = new MeshPhysicalNodeMaterial();
    m.colorNode = tileColorNode;
    m.roughness = 0.55;
    m.metalness = 0.5;
    m.clearcoat = 0.2;
    m.clearcoatRoughness = 0.4;
    m.anisotropy = 0.6;
    m.anisotropyRotation = 0; // aligned to x
    m.transparent = true;
    m.opacity = 0;
    disposables.push(m);
    return m;
  }

  // ---------------------------------------------------------------
  // TEXT CONTENT
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find((i) => i.role === 'kicker') || { text: 'AS FEATURED IN' };
  const markItems = items.filter((i) => i.role === 'brand-mark');

  function collectMaterials(obj) {
    const mats = [];
    obj.traverse((c) => {
      if (c.material) {
        const arr = Array.isArray(c.material) ? c.material : [c.material];
        for (const mm of arr) {
          mm.transparent = true;
          mats.push(mm);
        }
      }
    });
    return mats;
  }

  // Grid layout: 3 cols x 2 rows, gap 0.25 -> total 3.5 x 1.49, centered
  const colX = [-(TILE_W + GAP), 0, TILE_W + GAP];
  const rowY = [(TILE_H + GAP) / 2, -(TILE_H + GAP) / 2];
  const gridTop = rowY[0] + TILE_H / 2; // 0.745

  const tiles = [];
  const tileFadeSets = [];

  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 3; c++) {
      const idx = r * 3 + c;
      const item = markItems[idx];
      if (!item) continue;

      const tile = new Group();
      tile.position.set(colX[c], rowY[r], 0);
      tile.userData.tileIndex = idx;
      tile.userData.isBrandTile = true;

      const mat = makeTileMaterial();
      const mesh = new Mesh(tileGeo, mat);
      tile.add(mesh);

      const label = String(item.text || '');
      const fontSize = label.length > 10 ? 16 : 20;
      const text = ctx.fontAtlas.createText(label, {
        fontSize,
        color: paper,
        align: 'center',
        letterSpacingPx: fontSize * 0.08,
        maxWidthPx: 190
      });
      text.position.set(0, 0, DEPTH + CHAMFER + 0.015);
      tile.add(text);

      const textMats = collectMaterials(text);
      for (const tm of textMats) tm.opacity = 0;

      tile.userData.textMats = textMats;
      tile.userData.tileMat = mat;
      tile.userData.baseZ = 0;

      root.add(tile);
      tiles.push(tile);
      tileFadeSets.push({ tile, mat, textMats, baseY: rowY[r] });
    }
  }

  // ---------------------------------------------------------------
  // KICKER 0.3 above grid + accent tick (foreground depth plane)
  // ---------------------------------------------------------------
  const kicker = ctx.fontAtlas.createText(String(kickerItem.text || 'AS FEATURED IN'), {
    fontSize: 14,
    color: paper,
    align: 'center',
    letterSpacingPx: 14 * 0.12
  });
  kicker.position.set(0, gridTop + 0.3, 0.05);
  root.add(kicker);
  const kickerMats = collectMaterials(kicker);
  for (const km of kickerMats) km.opacity = 0;

  const tickGeo = new PlaneGeometry(0.18, 0.018);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = color(accent);
  tickMat.transparent = true;
  tickMat.opacity = 0;
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(0, gridTop + 0.3 - 0.09, 0.1);
  root.add(tick);
  disposables.push(tickGeo, tickMat);

  // ---------------------------------------------------------------
  // MOUNT: stagger-cards fade-up, top row L->R first, 500ms / 80ms
  // ---------------------------------------------------------------
  const tl = gsap.timeline();
  timelines.push(tl);

  tl.to(kickerMats, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.fromTo(kicker.position, { y: gridTop + 0.3 - 0.2 }, { y: gridTop + 0.3, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(tickMat, { opacity: 0.9, duration: 0.5, ease: 'power2.out' }, 0.12);

  tileFadeSets.forEach((set, i) => {
    const at = 0.15 + i * 0.08;
    tl.fromTo(set.tile.position, { y: set.baseY - 0.2 }, { y: set.baseY, duration: 0.5, ease: 'power2.out' }, at);
    tl.to(set.mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, at);
    tl.to(set.textMats, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, at + 0.08);
    // weighted settle: subtle overshoot 1.04 -> 1.0
    tl.fromTo(set.tile.scale, { x: 1, y: 1, z: 1 }, { x: 1.04, y: 1.04, z: 1, duration: 0.2, ease: 'power2.out' }, at + 0.3);
    tl.to(set.tile.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, at + 0.5);
  });

  // ---------------------------------------------------------------
  // HOVER: wordmark opacity 0.78 -> 1.0, tile z 0 -> 0.05, 160ms
  // ---------------------------------------------------------------
  function findTile(objOrHit) {
    let o = objOrHit && objOrHit.object ? objOrHit.object : objOrHit;
    while (o) {
      if (o.userData && o.userData.isBrandTile) return o;
      o = o.parent;
    }
    return null;
  }

  let hovered = null;

  function hoverIn(tile) {
    if (!tile || hovered === tile) return;
    hoverOut();
    hovered = tile;
    gsap.to(tile.position, { z: 0.05, duration: 0.16, ease: 'power2.out' });
    gsap.to(tile.userData.textMats, { opacity: 1.0, duration: 0.16, ease: 'power2.out' });
  }

  function hoverOut() {
    if (!hovered) return;
    gsap.to(hovered.position, { z: 0, duration: 0.16, ease: 'power2.out' });
    gsap.to(hovered.userData.textMats, { opacity: 0.78, duration: 0.16, ease: 'power2.out' });
    hovered = null;
  }

  root.userData.handlers = {
    pointermove: (hit) => {
      const tile = findTile(hit);
      if (tile) hoverIn(tile);
      else hoverOut();
    },
    pointerenter: (hit) => hoverIn(findTile(hit)),
    pointerleave: () => hoverOut(),
    hover: (hit) => hoverIn(findTile(hit)),
    unhover: () => hoverOut()
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const set of tileFadeSets) {
      gsap.killTweensOf(set.tile.position);
      gsap.killTweensOf(set.tile.scale);
      gsap.killTweensOf(set.mat);
      gsap.killTweensOf(set.textMats);
    }
    gsap.killTweensOf(kickerMats);
    gsap.killTweensOf(kicker.position);
    gsap.killTweensOf(tickMat);
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    root.traverse((c) => {
      if (c.geometry && typeof c.geometry.dispose === 'function') c.geometry.dispose();
    });
  };

  return root;
}
